import{_ as e,o as r,c as t,a2 as n}from"./chunks/framework.D8Tso2Ul.js";const u=JSON.parse('{"title":"Entrega de EPP","description":"","frontmatter":{},"headers":[],"relativePath":"ds44/epp.md","filePath":"ds44/epp.md"}'),o={name:"ds44/epp.md"};function s(d,a,i,l,c,p){return r(),t("div",null,[...a[0]||(a[0]=[n(`<h1 id="entrega-de-epp" tabindex="-1">Entrega de EPP <a class="header-anchor" href="#entrega-de-epp" aria-label="Permalink to &quot;Entrega de EPP&quot;">​</a></h1><p>La entrega de <strong>Elementos de Protección Personal (EPP)</strong> es una obligación central del DS 44: la empresa debe proporcionar los EPP adecuados al riesgo de cada cargo y dejar <strong>registro firmado</strong> de su entrega y recepción.</p><h2 id="el-acta-de-entrega-de-epp" tabindex="-1">El acta de entrega de EPP <a class="header-anchor" href="#el-acta-de-entrega-de-epp" aria-label="Permalink to &quot;El acta de entrega de EPP&quot;">​</a></h2><p>En Build &amp; Serve, cada entrega genera un documento de tipo <code>ENTREGA_EPP</code>. El acta incluye:</p><ul><li><strong>Trabajador receptor</strong>: nombre, RUT, cargo.</li><li><strong>Listado de EPP entregados</strong>: tipo, cantidad, fecha de entrega.</li><li><strong>Cargo y riesgo asociado</strong>: qué EPP corresponde según la MIPPER del cargo.</li><li><strong>Doble firma</strong>: del <strong>trabajador</strong> (recepción conforme) y del <strong>supervisor</strong> (entrega y verificación de uso correcto).</li></ul><h2 id="flujo-de-entrega" tabindex="-1">Flujo de entrega <a class="header-anchor" href="#flujo-de-entrega" aria-label="Permalink to &quot;Flujo de entrega&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>1. Supervisor crea el acta ENTREGA_EPP para un trabajador</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>2. Se asigna al trabajador → notificación en su bandeja de entrada</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>3. El trabajador firma la recepción (PIN o presencial)</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>4. El supervisor firma la entrega</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>5. El acta queda en estado &quot;completado&quot; en SignaturesTable (inmutable)</span></span></code></pre></div><h2 id="matriz-de-epp-por-cargo" tabindex="-1">Matriz de EPP por cargo <a class="header-anchor" href="#matriz-de-epp-por-cargo" aria-label="Permalink to &quot;Matriz de EPP por cargo&quot;">​</a></h2><p>El tipo de EPP a entregar se deriva de la <strong>MIPPER</strong> del cargo del trabajador. La matriz de riesgos define, para cada cargo y actividad, qué protección es obligatoria. De este modo la entrega de EPP queda alineada con la evaluación de riesgos y no es arbitraria.</p><table tabindex="0"><thead><tr><th>Ejemplo de cargo</th><th>EPP típico (según MIPPER)</th></tr></thead><tbody><tr><td>Maestro albañil</td><td>Casco, guantes, calzado de seguridad, lentes</td></tr><tr><td>Operador de excavadora</td><td>Casco, protección auditiva, chaleco reflectante</td></tr><tr><td>Trabajador en altura</td><td>Arnés, casco con barbiquejo, línea de vida</td></tr><tr><td>Soldador</td><td>Máscara de soldar, guantes de cuero, coleto, polainas</td></tr></tbody></table><blockquote><p>Los valores son ilustrativos; la matriz real se configura por cargo en cada obra a través de la <a href="/manual/ds44/documentos-obligatorios.html">MIPPER</a>.</p></blockquote><h2 id="trazabilidad-ante-fiscalizacion" tabindex="-1">Trazabilidad ante fiscalización <a class="header-anchor" href="#trazabilidad-ante-fiscalizacion" aria-label="Permalink to &quot;Trazabilidad ante fiscalización&quot;">​</a></h2><p>Cada acta firmada queda registrada en <code>SignaturesTable</code> con PIN, IP y timestamp, lo que permite demostrar ante un fiscalizador:</p><ul><li><strong>Qué</strong> EPP se entregó.</li><li><strong>A quién</strong> y en qué fecha.</li><li><strong>Quién</strong> autorizó y verificó la entrega.</li></ul><p>Consulta el detalle del registro de firmas en <a href="/manual/ds44/firmas-digitales.html">Firmas digitales y DS44</a>.</p>`,15)])])}const P=e(o,[["render",s]]);export{u as __pageData,P as default};
